Problem statement:
Sort integers.

The first line contains n (0 <= n <= 100000). The second line contains n integers; each fits in a
signed 32-bit int (-2147483648 .. 2147483647).

Print the n integers in non-decreasing order on one line, separated by single spaces, followed by a
newline. When n = 0 print just a newline. The solution must run in O(n log n) time.

Sample input:
5
3 1 4 1 5

Sample output:
1 1 3 4 5

Student file sort_merge.c:
  1 | /*
  2 |  * sort_merge.c - sorts n integers in non-decreasing order with merge sort.
  3 |  * Input:  n, then n integers.   Output: the sorted values on one line.
  4 |  * Time O(n log n), extra memory O(n).
  5 |  */
  6 | #include <stdio.h>
  7 | #include <stdlib.h>
  8 | 
  9 | /* Merges the sorted runs values[left..mid) and values[mid..right) via scratch. */
 10 | static void merge(int *values, int *scratch, size_t left, size_t mid, size_t right)
 11 | {
 12 |     size_t i = left, j = mid, k = left;
 13 | 
 14 |     while (i < mid && j < right) {
 15 |         if (values[i] <= values[j]) {
 16 |             scratch[k++] = values[i++];
 17 |         } else {
 18 |             scratch[k++] = values[j++];
 19 |         }
 20 |     }
 21 |     while (i < mid) {
 22 |         scratch[k++] = values[i++];
 23 |     }
 24 |     while (j < right) {
 25 |         scratch[k++] = values[j++];
 26 |     }
 27 |     for (k = left; k < right; k++) {
 28 |         values[k] = scratch[k];
 29 |     }
 30 | }
 31 | 
 32 | /* Sorts values[left..right) recursively. */
 33 | static void merge_sort(int *values, int *scratch, size_t left, size_t right)
 34 | {
 35 |     if (right - left < 2) {
 36 |         return;
 37 |     }
 38 |     size_t mid = left + (right - left) / 2;
 39 |     merge_sort(values, scratch, left, mid);
 40 |     merge_sort(values, scratch, mid, right);
 41 |     merge(values, scratch, left, mid, right);
 42 | }
 43 | 
 44 | /* Reads count integers into a new array; returns NULL on bad input or no memory. */
 45 | static int *read_values(size_t count)
 46 | {
 47 |     int *values = malloc((count > 0 ? count : 1) * sizeof *values);
 48 | 
 49 |     if (values == NULL) {
 50 |         return NULL;
 51 |     }
 52 |     for (size_t i = 0; i < count; i++) {
 53 |         if (scanf("%d", &values[i]) != 1) {
 54 |             free(values);
 55 |             return NULL;
 56 |         }
 57 |     }
 58 |     return values;
 59 | }
 60 | 
 61 | /* Prints the values separated by single spaces, then a newline. */
 62 | static void print_values(const int *values, size_t count)
 63 | {
 64 |     for (size_t i = 0; i < count; i++) {
 65 |         printf(i == 0 ? "%d" : " %d", values[i]);
 66 |     }
 67 |     printf("\n");
 68 | }
 69 | 
 70 | int main(void)
 71 | {
 72 |     int count;
 73 | 
 74 |     if (scanf("%d", &count) != 1 || count < 0) {
 75 |         fprintf(stderr, "error: expected a non-negative count\n");
 76 |         return EXIT_FAILURE;
 77 |     }
 78 |     size_t length = (size_t)count;
 79 |     int *values = read_values(length);
 80 |     int *scratch = malloc((length > 0 ? length : 1) * sizeof *scratch);
 81 |     if (values == NULL || scratch == NULL) {
 82 |         free(values);
 83 |         free(scratch);
 84 |         fprintf(stderr, "error: could not read the input\n");
 85 |         return EXIT_FAILURE;
 86 |     }
 87 |     merge_sort(values, scratch, 0, length);
 88 |     print_values(values, length);
 89 |     free(scratch);
 90 |     free(values);
 91 |     return EXIT_SUCCESS;
 92 | }
